## 5. Production n8n JavaScript RRF Merging Code Node

The following production JavaScript code node runs inside n8n. It accepts two parallel input streams—dense vector hits and sparse keyword hits—computes RRF score values with $k=60$, handles missing payload fields, and returns the top re-ranked document items.

```javascript
// n8n Code Node: Reciprocal Rank Fusion (RRF) Merging & Re-Ranking Engine
const items = $input.all();
const RRF_K = 60; // Smoothing constant
const TOP_K = 5;  // Final top documents to retain

const combinedHitsMap = new Map();

items.forEach((item) => {
  const denseHits = item.json.denseResults || [];
  const sparseHits = item.json.sparseResults || [];

  // Process Dense Vector Search Results (List 1)
  denseHits.forEach((hit, index) => {
    const docId = hit.id || hit.payload?.doc_id;
    const rank = index + 1; // 1-based rank
    const rrfScore = 1.0 / (RRF_K + rank);

    if (!combinedHitsMap.has(docId)) {
      combinedHitsMap.set(docId, {
        id: docId,
        score_rrf: 0.0,
        dense_rank: rank,
        sparse_rank: null,
        dense_score: hit.score || 0.0,
        sparse_score: 0.0,
        payload: hit.payload || {}
      });
    }

    const docEntry = combinedHitsMap.get(docId);
    docEntry.score_rrf += rrfScore;
    docEntry.dense_rank = rank;
    docEntry.dense_score = hit.score || 0.0;
  });

  // Process Sparse BM25 Search Results (List 2)
  sparseHits.forEach((hit, index) => {
    const docId = hit.id || hit.payload?.doc_id;
    const rank = index + 1; // 1-based rank
    const rrfScore = 1.0 / (RRF_K + rank);

    if (!combinedHitsMap.has(docId)) {
      combinedHitsMap.set(docId, {
        id: docId,
        score_rrf: 0.0,
        dense_rank: null,
        sparse_rank: rank,
        dense_score: 0.0,
        sparse_score: hit.score || 0.0,
        payload: hit.payload || {}
      });
    }

    const docEntry = combinedHitsMap.get(docId);
    docEntry.score_rrf += rrfScore;
    docEntry.sparse_rank = rank;
    docEntry.sparse_score = hit.score || 0.0;

    if (Object.keys(docEntry.payload).length === 0 && hit.payload) {
      docEntry.payload = hit.payload;
    }
  });
});

const sortedResults = Array.from(combinedHitsMap.values())
  .sort((a, b) => b.score_rrf - a.score_rrf)
  .slice(0, TOP_K);

return sortedResults.map((doc, idx) => ({
  json: {
    final_rank: idx + 1,
    id: doc.id,
    rrf_score: parseFloat(doc.score_rrf.toFixed(6)),
    dense_rank: doc.dense_rank,
    sparse_rank: doc.sparse_rank,
    text: doc.payload.text || '',
    metadata: doc.payload
  }
}));
```

