      "values": {{$json.body.sparse_values}}
    }
  },
  "limit": 10,
  "with_payload": true
}"
      },
      "name": "Qdrant Sparse BM25 Search",
      "type": "n8n-nodes-base.httpRequest",
      "typeVersion": 4.1,
      "position": [450, 400]
    },
    {
      "parameters": {
        "jsCode": "const denseHits = $items("Qdrant Dense Vector Search").map(i => i.json.result).flat();
const sparseHits = $items("Qdrant Sparse BM25 Search").map(i => i.json.result).flat();

const RRF_K = 60;
const map = new Map();

denseHits.forEach((hit, idx) => {
  const id = hit.id;
  const rrf = 1 / (RRF_K + idx + 1);
  map.set(id, { id, score: rrf, denseRank: idx + 1, sparseRank: null, payload: hit.payload });
});

sparseHits.forEach((hit, idx) => {
  const id = hit.id;
  const rrf = 1 / (RRF_K + idx + 1);
  if (map.has(id)) {
    const entry = map.get(id);
    entry.score += rrf;
    entry.sparseRank = idx + 1;
  } else {
    map.set(id, { id, score: rrf, denseRank: null, sparseRank: idx + 1, payload: hit.payload });
  }
});

const sorted = Array.from(map.values()).sort((a, b) => b.score - a.score).slice(0, 5);
return sorted.map(item => ({ json: item }));"
